"""Alembic environment generated by Component 3 - Data Layer Migration."""

import importlib.util
import os
from logging.config import fileConfig
from pathlib import Path

from alembic import context
from sqlalchemy import create_engine, pool
from sqlalchemy.engine import make_url

config = context.config

if config.config_file_name is not None:
    fileConfig(config.config_file_name, disable_existing_loggers=False)

# target_metadata is the generated models.py next to this alembic/ folder.
_MODELS_FILE = Path(__file__).resolve().parent.parent / "models.py"
_spec = importlib.util.spec_from_file_location("c3_generated_models", _MODELS_FILE)
_models = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(_models)

target_metadata = _models.Base.metadata


def _database_url():
    url = os.environ.get("C3_ALEMBIC_URL") or config.get_main_option("sqlalchemy.url")

    if not url:
        raise RuntimeError(
            "Set C3_ALEMBIC_URL, e.g. mysql+pymysql://c3_tester@127.0.0.1/c3_e3_myapp "
            "(the password is taken from C3_DB_PASSWORD; never write it to a file)."
        )

    parsed = make_url(url)

    # SQLite URLs take no password (setting one makes the URL invalid).
    if (
        parsed.password is None
        and os.environ.get("C3_DB_PASSWORD")
        and parsed.get_backend_name() != "sqlite"
    ):
        parsed = parsed.set(password=os.environ["C3_DB_PASSWORD"])

    return parsed


def run_migrations_offline():
    context.configure(
        url=_database_url(),
        target_metadata=target_metadata,
        literal_binds=True,
        dialect_opts={"paramstyle": "named"},
        compare_type=True,
    )

    with context.begin_transaction():
        context.run_migrations()


def run_migrations_online():
    engine = create_engine(_database_url(), poolclass=pool.NullPool)

    with engine.connect() as connection:
        context.configure(
            connection=connection,
            target_metadata=target_metadata,
            compare_type=True,
        )

        with context.begin_transaction():
            context.run_migrations()


if context.is_offline_mode():
    run_migrations_offline()
else:
    run_migrations_online()
